do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'ENGLISH_RELATE_LANGUAGE_CULTURE';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 6, 'Linguagem, público e contexto', 'Uma forma de dizer não é universalmente melhor. Use pistas do texto e da situação, reconheça variedades e idioms e evite transformar um exemplo local em regra sobre todas as pessoas.', '## 1. Identifique a situação
Antes de interpretar uma mensagem, pergunte: quem fala, para quem, por qual canal e com qual objetivo? Uma conversa entre colegas, um aviso público e um e-mail para uma coordenação podem tratar do mesmo assunto com escolhas diferentes.

## 2. Observe marcas linguísticas
Saudações, contrações, imperativos, modalizadores como “could” e “might”, vocativos e nível de detalhe ajudam a descrever registro e tom. Uma forma direta pode ser clara e respeitosa em um contexto; uma forma mais formal pode ser adequada em outro. Formalidade não mede inteligência, caráter ou valor de quem fala.

## 3. Interprete expressões no contexto
Idioms e phrasal verbs nem sempre significam a soma literal das palavras. Use a situação, a frase ao redor e a resposta de outras pessoas. “On the same page” pode indicar entendimento compartilhado; “look over” pode significar revisar. Se contexto suficiente não existir, peça esclarecimento em vez de adivinhar.

## 4. Reconheça variedades de inglês
Inglês é usado em comunidades diversas. Ortografia, vocabulário, pronúncia e convenções podem variar. Descreva uma forma com contexto e fonte; não trate uma variedade como inferior nem generalize um exemplo para todos os falantes. Uma preferência editorial pode ser definida por um guia de estilo sem virar juízo sobre pessoas.

## 5. Faça afirmações proporcionais
Use “nesta conversa” quando a evidência é local. Uma resposta positiva pode indicar acolhimento neste intercâmbio, não uma regra universal. Uma família pode explicar sua própria tradição; isso não fala automaticamente por toda uma comunidade. Distinga evidência, interpretação possível e informação ainda desconhecida.',
    'Compare “Could you send the notes when you have a moment?” em um pedido de colega para colega com “Send the notes now” em uma equipe que combinou urgência. A primeira formulação é menos direta; a segunda explicita urgência. O contexto pode explicar ambas. Só as frases, sem relação, canal e objetivo, não provam respeito ou hostilidade.', array['Marque audience, purpose e channel antes de interpretar.', 'Aponte uma palavra ou resposta como evidência para o tom.', 'Use “in this exchange” quando a conclusão depende de um caso local.']::text[], 26, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-english-relate-language-culture-contextual-use","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Compreender instruções e mensagens curtas em inglês.","Reconhecer perguntas, pedidos e conectores comuns."],"key_concepts":["audience and purpose","register and directness","idioms and phrasal verbs","English varieties","contextual evidence","stereotype and overgeneralization","clarification"],"progression":[{"stage":"DIAGNOSTIC","focus":"Reconhecer pistas de saudação, pedido, idiom e canal.","questionIds":["v5-english-relate-language-culture-01","v5-english-relate-language-culture-02","v5-english-relate-language-culture-03","v5-english-relate-language-culture-04"]},{"stage":"PRACTICE","focus":"Interpretar registro, variedades, idioms, certeza e clareza para diferentes públicos.","questionIds":["v5-english-relate-language-culture-05","v5-english-relate-language-culture-06","v5-english-relate-language-culture-07","v5-english-relate-language-culture-08","v5-english-relate-language-culture-09","v5-english-relate-language-culture-10","v5-english-relate-language-culture-11","v5-english-relate-language-culture-12","v5-english-relate-language-culture-13","v5-english-relate-language-culture-14","v5-english-relate-language-culture-15"]},{"stage":"TRANSFER","focus":"Adaptar mensagens e interpretar ambiguidade, referências e humor com limites.","questionIds":["v5-english-relate-language-culture-16","v5-english-relate-language-culture-17","v5-english-relate-language-culture-18","v5-english-relate-language-culture-19","v5-english-relate-language-culture-20","v5-english-relate-language-culture-21","v5-english-relate-language-culture-22","v5-english-relate-language-culture-23"]},{"stage":"CONSOLIDATION","focus":"Rejeitar hierarquias de sotaque e generalizações culturais.","questionIds":["v5-english-relate-language-culture-24","v5-english-relate-language-culture-25","v5-english-relate-language-culture-26"]},{"stage":"REVIEW","focus":"Reaplicar o método de contexto e pedir esclarecimento quando necessário.","questionIds":["v5-english-relate-language-culture-27","v5-english-relate-language-culture-28","v5-english-relate-language-culture-29"]}],"micro_explanations":[{"trigger":"AUDIENCE_PURPOSE_CHANNEL","text":"Audience, purpose and channel help explain which register fits a situation."},{"trigger":"REGISTER_NOT_RANK","text":"Formal and informal choices serve different contexts; neither ranks a speaker’s intelligence or worth."},{"trigger":"IDIOM_FROM_CONTEXT","text":"When a literal reading does not fit, use surrounding clues to test an idiomatic meaning."},{"trigger":"VARIETY_NOT_UNIVERSAL","text":"One spelling or expression is evidence about a usage in context, not a rule for every English-speaking community."},{"trigger":"UNCERTAINTY_CAN_BE_CLARIFIED","text":"If the exchange does not resolve an ambiguity, ask a neutral question instead of guessing."}],"remediations":[{"id":"MAP_THE_INTERACTION","misconception":"Julgar a mensagem sem identificar interlocutores e canal.","prompt":"Complete: “The speaker is ___; the audience is ___; the purpose is ___; the channel is ___.” Re-read the phrase with those details."},{"id":"TEST_IDIOM","misconception":"Traduzir uma expressão palavra por palavra.","prompt":"Write the literal meaning, then check whether it fits the situation. Use the surrounding action or reply to test a figurative meaning."},{"id":"LIMIT_THE_CLAIM","misconception":"Transformar um exemplo em regra para todos os falantes.","prompt":"Rewrite the claim with “in this exchange” or name the source and community. Remove “always” unless the evidence supports it."},{"id":"SEPARATE_REGISTER_AND_WORTH","misconception":"Usar formalidade ou sotaque para avaliar capacidade.","prompt":"Replace the personal ranking with a specific question about clarity, audience or purpose in this situation."},{"id":"ASK_WHEN_UNCLEAR","misconception":"Preencher uma ambiguidade com suposição cultural.","prompt":"Write a neutral clarification question that names the phrase and asks what the speaker means here."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"publisher":"Ministério da Educação, Brasil","title":"Base Nacional Comum Curricular","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","license":"Referência curricular geral; alinhamento oficial específico não reivindicado."}],"copyright_note":"Diálogos, mensagens, questões e feedbacks são autorais e fictícios. Exemplos evitam atribuir uma convenção a todas as pessoas de uma comunidade. Revisão pedagógica pendente; sem mapeamento oficial reivindicado.","source_question_feedback":[{"questionId":"v93-eng-culture-01","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-02","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-03","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-04","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-05","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-06","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-07","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-08","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-09","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-10","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-11","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-12","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-13","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-14","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-15","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-16","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-17","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-18","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-19","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"},{"questionId":"v93-eng-culture-20","hint":"Identify the audience, purpose and channel first. Use words in the exchange as evidence, and avoid turning one local convention into a rule for all English speakers.","errorFocus":"LANGUAGE_CONTEXT_VARIETY_AND_SCOPE"}],"objective":"Interpretar escolhas de registro, expressões e convenções em inglês considerando interlocutores, finalidade, canal e diversidade de usos.","common_mistake":"Traduzir idioms palavra por palavra, julgar capacidade por formalidade ou sotaque, ou generalizar uma convenção observada para todas as comunidades de inglês.","estimated_minutes":26}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 6
     and metadata->>'content_id' = 'v5-english-relate-language-culture-contextual-use' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-english-relate-language-culture-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"GREETING_IN_CLASS_CHAT","statement":"A classmate writes “Hi, Maya!” in a group chat before asking about homework. Which feature is visible in the greeting?","options":["A brief, familiar greeting suited to a peer conversation.","A formal title that identifies a school official.","A guarantee that the homework is easy.","A phrase that proves the writer is being disrespectful."],"correctAnswer":"A brief, familiar greeting suited to a peer conversation.","explanation":"“Hi” and the classmate relationship support an informal reading. Informal wording is not automatically disrespectful.","hint":"Identify the relationship and channel before judging the greeting.","errorFocus":"INFORMAL_REGISTER_TREATED_AS_INCORRECT","misconceptions":{"A formal title that identifies a school official.":["INFORMAL_REGISTER_TREATED_AS_INCORRECT"]},"position":1},{"id":"v5-english-relate-language-culture-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"POLITE_REQUEST_MARKER","statement":"A student writes to a club coordinator: “Could you share the meeting room when you have time?” What does “could you” do here?","options":["It proves the student is unsure that a room exists.","It frames the request less directly than an imperative.","It changes the request into a past event.","It means the coordinator is required to answer immediately."],"correctAnswer":"It frames the request less directly than an imperative.","explanation":"The modal wording softens the request. It does not establish uncertainty about the room or an immediate deadline.","hint":"Compare it with “Share the room now” and notice the difference in directness.","errorFocus":"MODAL_REQUEST_MISREAD","misconceptions":{"It proves the student is unsure that a room exists.":["MODAL_REQUEST_MISREAD"]},"position":2},{"id":"v5-english-relate-language-culture-03","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"IDIOM_CONTEXT_CLUE","statement":"Before a group presentation, one student says, “Let’s get everyone on the same page.” What is the likely meaning?","options":["Open a book to an identical page number.","Ask everyone to leave the group.","Make sure the group shares the same understanding or plan.","Rewrite the presentation in another language."],"correctAnswer":"Make sure the group shares the same understanding or plan.","explanation":"The presentation context suggests coordinating understanding, not physically opening a book.","hint":"Ask what action would help the group prepare together.","errorFocus":"IDIOM_TRANSLATED_WORD_FOR_WORD","misconceptions":{"Open a book to an identical page number.":["IDIOM_TRANSLATED_WORD_FOR_WORD"]},"position":3},{"id":"v5-english-relate-language-culture-04","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"IDENTIFY","contextFamily":"AUDIENCE_AND_CHANNEL","statement":"A notice in a school app says, “Please submit the form by Friday.” Which details help interpret the request?","options":["The notice proves the form is optional.","The app determines the writer’s accent.","Friday means the form was already submitted.","The app is the channel, and Friday is the stated deadline."],"correctAnswer":"The app is the channel, and Friday is the stated deadline.","explanation":"The channel and explicit deadline are stated. Other requirements would need more information.","hint":"Separate what the message says from what it does not say.","errorFocus":"MESSAGE_DETAILS_OVERINFERRED","misconceptions":{"The notice proves the form is optional.":["MESSAGE_DETAILS_OVERINFERRED"]},"position":4},{"id":"v5-english-relate-language-culture-05","purpose":"PRACTICE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"PEER_TEXT_TONE","statement":"A friend texts, “I’m running a little late. Could you save me a seat?” Which description best fits the message?","options":["A familiar, concise request that gives a reason and asks for help.","A formal legal notice with no request.","A command proving the friendship has ended.","A report that the event has been cancelled."],"correctAnswer":"A familiar, concise request that gives a reason and asks for help.","explanation":"The text gives a short explanation and a softened request in a familiar channel.","hint":"Use the relationship, explanation and question form as evidence.","errorFocus":"TONE_JUDGED_WITHOUT_CONTEXT","misconceptions":{"A formal legal notice with no request.":["TONE_JUDGED_WITHOUT_CONTEXT"]},"position":1},{"id":"v5-english-relate-language-culture-06","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"EMAIL_FOR_COORDINATOR","statement":"A student needs to ask a school coordinator to move an appointment. Which opening best makes the purpose clear and considerate?","options":["“Move it. I cannot come.”","“Hello, Ms. Lee. Could we reschedule my appointment on Tuesday? I am available after 2 p.m.”","“Hey!!! Change everything now!!!”","“The appointment was moved,” even though no change has been agreed."],"correctAnswer":"“Hello, Ms. Lee. Could we reschedule my appointment on Tuesday? I am available after 2 p.m.”","explanation":"The message names the recipient, states the request and offers relevant availability without claiming the change is already confirmed.","hint":"Check that the message gives a request, not an unsupported statement of completion.","errorFocus":"REQUEST_CONFUSED_WITH_CONFIRMED_ACTION","misconceptions":{"“Move it. I cannot come.”":["REQUEST_CONFUSED_WITH_CONFIRMED_ACTION"]},"position":2},{"id":"v5-english-relate-language-culture-07","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"REGIONAL_LEXICAL_VARIANT","statement":"A visitor reads a sign that says “Please leave your flat key at reception.” The visitor is in a place where “flat” is used for an apartment. What does the word mean in this context?","options":["A bicycle tire.","A musical note.","An apartment key.","A level surface."],"correctAnswer":"An apartment key.","explanation":"The lodging and reception context support the regional housing meaning of “flat”.","hint":"Use the surrounding situation instead of choosing a meaning from the word alone.","errorFocus":"POLYSEMY_WITHOUT_CONTEXT","misconceptions":{"A bicycle tire.":["POLYSEMY_WITHOUT_CONTEXT"]},"position":3},{"id":"v5-english-relate-language-culture-08","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"IDIOM_AT_WORK","statement":"After a teammate discovers a mistake in a shared plan, another says, “No need to spill the beans; let’s check the draft first.” What does “spill the beans” most likely mean?","options":["Drop a bag of groceries.","Correct the draft carefully.","End the project without telling anyone.","Reveal information before the group is ready to share it."],"correctAnswer":"Reveal information before the group is ready to share it.","explanation":"The reference to checking a draft suggests the phrase concerns revealing information, not literal food.","hint":"Connect the idiom to the draft and the timing of sharing.","errorFocus":"IDIOM_IGNORED_CONTEXT","misconceptions":{"Drop a bag of groceries.":["IDIOM_IGNORED_CONTEXT"]},"position":4},{"id":"v5-english-relate-language-culture-09","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ANALYZE","contextFamily":"DIRECTNESS_AND_URGENCY","statement":"A teammate writes, “Please send the slides by 3 p.m. so I can combine them before the meeting.” Which evidence explains the direct request?","options":["The message states a deadline and a reason tied to a shared task.","The message proves the sender is angry.","The request is direct, so it cannot be polite.","The sender wants the slides after the meeting."],"correctAnswer":"The message states a deadline and a reason tied to a shared task.","explanation":"A clear deadline and practical reason support the request. Directness alone does not prove anger or impoliteness.","hint":"Look for the stated time and purpose rather than inferring emotion.","errorFocus":"DIRECTNESS_EQUALLED_WITH_HOSTILITY","misconceptions":{"The message proves the sender is angry.":["DIRECTNESS_EQUALLED_WITH_HOSTILITY"]},"position":5},{"id":"v5-english-relate-language-culture-10","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"VARIETY_WITHOUT_HIERARCHY","statement":"Two collaborators use “organise” and “organize” in otherwise similar notes. What is the most careful interpretation?","options":["One spelling proves the writer understands English better.","They use different accepted spelling conventions; the spelling alone does not show ability.","One spelling is always incorrect in every English-speaking setting.","The difference changes the meaning of the word."],"correctAnswer":"They use different accepted spelling conventions; the spelling alone does not show ability.","explanation":"Both spellings are used in English conventions. A style guide or audience may determine which one to use in a document.","hint":"Separate convention choice from a judgment about the writer.","errorFocus":"VARIETY_RANKED_BY_SPELLING","misconceptions":{"One spelling proves the writer understands English better.":["VARIETY_RANKED_BY_SPELLING"]},"position":6},{"id":"v5-english-relate-language-culture-11","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"PHRASAL_VERB_CONTEXT","statement":"A message says, “Could you look over the schedule before we publish it?” What action is requested?","options":["Look at the schedule from above.","Publish it immediately without review.","Review the schedule.","Remove the schedule from the message."],"correctAnswer":"Review the schedule.","explanation":"“Look over” means review in this editing context.","hint":"Use the planned publication as a clue to the verb phrase.","errorFocus":"PHRASAL_VERB_LITERALIZED","misconceptions":{"Look at the schedule from above.":["PHRASAL_VERB_LITERALIZED"]},"position":7},{"id":"v5-english-relate-language-culture-12","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"EVALUATE","contextFamily":"HEDGING_AND_CERTAINTY","statement":"A project note says, “This change may reduce loading time; we need to test it.” What claim does the note make?","options":["Loading time definitely improved for every user.","The change cannot affect loading time.","Testing has already proved the result.","The improvement is possible but not yet confirmed."],"correctAnswer":"The improvement is possible but not yet confirmed.","explanation":"“May” marks possibility, and the note explicitly says more testing is needed.","hint":"Keep the strength of the conclusion equal to the words used.","errorFocus":"POSSIBILITY_READ_AS_CERTAINTY","misconceptions":{"Loading time definitely improved for every user.":["POSSIBILITY_READ_AS_CERTAINTY"]},"position":8},{"id":"v5-english-relate-language-culture-13","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"COURTESY_FORMULA","statement":"After someone apologizes for a delay, a colleague replies, “No worries; thanks for letting me know.” What does “no worries” do in this exchange?","options":["It reassures the colleague that the delay is being accepted in this interaction.","It proves delays never matter in any workplace.","It tells the colleague to stop communicating.","It cancels every future deadline."],"correctAnswer":"It reassures the colleague that the delay is being accepted in this interaction.","explanation":"The reply acknowledges the apology and reduces tension in this exchange; it is not a universal rule about deadlines.","hint":"Keep the interpretation within this conversation.","errorFocus":"LOCAL_COURTESY_GENERALIZED","misconceptions":{"It proves delays never matter in any workplace.":["LOCAL_COURTESY_GENERALIZED"]},"position":9},{"id":"v5-english-relate-language-culture-14","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"AUDIENCE_EXPLICITNESS","statement":"A public library invites visitors from many language backgrounds to a workshop. Which announcement is easiest to act on?","options":["“Come then for the thing we discussed.”","“Join the free book-repair workshop on Saturday at 10 a.m. Register at the front desk.”","“You know what to do; bring everything.”","“It happens soon somewhere in the building.”"],"correctAnswer":"“Join the free book-repair workshop on Saturday at 10 a.m. Register at the front desk.”","explanation":"The first announcement names the activity, cost, time and action. The alternatives rely on missing shared context.","hint":"Check whether a new visitor can identify what, when and how to join.","errorFocus":"SHARED_CONTEXT_ASSUMED_FOR_PUBLIC_MESSAGE","misconceptions":{"“Come then for the thing we discussed.”":["SHARED_CONTEXT_ASSUMED_FOR_PUBLIC_MESSAGE"]},"position":10},{"id":"v5-english-relate-language-culture-15","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"METAPHOR_IN_CONTEXT","statement":"A student says, “That explanation opened a door for me,” after understanding a difficult topic. What is the likely figurative meaning?","options":["A physical door was installed in the classroom.","The student is leaving the lesson immediately.","The explanation made a new idea or possibility accessible.","The explanation removed every future challenge."],"correctAnswer":"The explanation made a new idea or possibility accessible.","explanation":"In a learning context, “opened a door” suggests access to a new understanding, not a literal door or a guaranteed outcome.","hint":"Connect the phrase to the change in understanding described.","errorFocus":"METAPHOR_READ_AS_LITERAL_OR_UNLIMITED","misconceptions":{"A physical door was installed in the classroom.":["METAPHOR_READ_AS_LITERAL_OR_UNLIMITED"]},"position":11},{"id":"v5-english-relate-language-culture-16","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"ADAPT","contextFamily":"CHANNEL_AND_RELATION","statement":"A student must send the same update to a close project partner and to a school office. Which strategy best fits both audiences?","options":["Use the most formal wording in every conversation, regardless of purpose.","Use slang in both messages so they sound identical.","Change the facts to match what each audience prefers.","Keep the facts consistent, but adjust greeting, detail and register to each relationship and channel."],"correctAnswer":"Keep the facts consistent, but adjust greeting, detail and register to each relationship and channel.","explanation":"Register can change while the factual content remains consistent. Audience and channel influence presentation, not the truth of the update.","hint":"Separate stable information from choices about tone and detail.","errorFocus":"REGISTER_ADAPTATION_CONFUSED_WITH_FACT_CHANGE","misconceptions":{"Use the most formal wording in every conversation, regardless of purpose.":["REGISTER_ADAPTATION_CONFUSED_WITH_FACT_CHANGE"]},"position":1},{"id":"v5-english-relate-language-culture-17","purpose":"TRANSFER","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"AMBIGUOUS_REPLY","statement":"After a meeting invitation, a colleague replies, “I’ll see what I can do.” What can be concluded without more context?","options":["The colleague has not made a definite commitment yet.","The colleague has certainly accepted.","The colleague has certainly refused.","The colleague will arrive at an exact time."],"correctAnswer":"The colleague has not made a definite commitment yet.","explanation":"The wording signals possibility rather than a firm yes or no. Follow-up may be needed to clarify plans.","hint":"Notice whether the reply commits to an action or leaves it open.","errorFocus":"AMBIGUOUS_REPLY_FORCED_TO_YES_OR_NO","misconceptions":{"The colleague has certainly accepted.":["AMBIGUOUS_REPLY_FORCED_TO_YES_OR_NO"]},"position":2},{"id":"v5-english-relate-language-culture-18","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"SLANG_WITH_LOCAL_CONTEXT","statement":"A student says “That was wicked” after a teammate completes a difficult skateboarding move; the teammate smiles and replies “Thanks.” What is the most supported reading here?","options":["The student is warning that the move was dangerous.","In this exchange, “wicked” is being used as praise.","The word has only one meaning in every English variety.","The reply proves every audience uses “wicked” as praise."],"correctAnswer":"In this exchange, “wicked” is being used as praise.","explanation":"The activity and positive response support praise in this exchange. The example does not define usage for all communities.","hint":"Use the immediate activity and response, then limit the claim to this interaction.","errorFocus":"SLANG_CONTEXT_GENERALIZED_TO_ALL_SPEAKERS","misconceptions":{"The student is warning that the move was dangerous.":["SLANG_CONTEXT_GENERALIZED_TO_ALL_SPEAKERS"]},"position":3},{"id":"v5-english-relate-language-culture-19","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"TRANSLATION_AND_IDIOM","statement":"A learner translates “It’s raining cats and dogs” word for word in a weather conversation. What would be a more useful next step?","options":["Assume animals are literally falling from the sky.","Replace every English word with the first dictionary meaning.","Check whether the phrase is an idiom and use the weather context to infer heavy rain.","Conclude that the speaker has changed the topic to pets."],"correctAnswer":"Check whether the phrase is an idiom and use the weather context to infer heavy rain.","explanation":"The weather context supports the idiomatic meaning “raining heavily”. Context helps avoid a literal translation.","hint":"Ask whether the literal meaning fits the situation.","errorFocus":"IDIOM_TRANSLATION_LITERAL","misconceptions":{"Assume animals are literally falling from the sky.":["IDIOM_TRANSLATION_LITERAL"]},"position":4},{"id":"v5-english-relate-language-culture-20","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CULTURAL_REFERENCE_AND_SOURCE","statement":"A school newsletter describes a celebration and links a note written by the participating family. What is the best way to explain a tradition mentioned in the note?","options":["State that one family’s account defines the tradition for everyone.","Replace the family’s explanation with a guess based on a symbol.","Omit the source and present the explanation as universal fact.","Attribute the explanation to that family and avoid presenting it as the practice of every family or community."],"correctAnswer":"Attribute the explanation to that family and avoid presenting it as the practice of every family or community.","explanation":"The source gives a situated perspective. Attribution preserves its value without generalizing beyond the people who shared it.","hint":"Name who provided the explanation and whose experience it describes.","errorFocus":"SITUATED_ACCOUNT_UNIVERSALIZED","misconceptions":{"State that one family’s account defines the tradition for everyone.":["SITUATED_ACCOUNT_UNIVERSALIZED"]},"position":5},{"id":"v5-english-relate-language-culture-21","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ADAPT","contextFamily":"REVISE_FOR_CLARITY","statement":"A message to a new exchange partner says, “Bring it there after the thing.” Which revision best reduces ambiguity?","options":["“Please bring the signed permission form to the library desk after class on Thursday.”","“Bring it there then.”","“You know which thing I mean.”","“Bring something somewhere after school.”"],"correctAnswer":"“Please bring the signed permission form to the library desk after class on Thursday.”","explanation":"The revision identifies the object, place and time, which are not recoverable from the original without shared context.","hint":"Replace each vague reference with the specific information the reader needs.","errorFocus":"DEICTIC_REFERENCE_WITHOUT_SHARED_CONTEXT","misconceptions":{"“Bring it there then.”":["DEICTIC_REFERENCE_WITHOUT_SHARED_CONTEXT"]},"position":6},{"id":"v5-english-relate-language-culture-22","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"REGISTER_AND_POWER","statement":"A service worker and a customer use different levels of formality in a conversation. What should an analyst examine before judging either speaker?","options":["Which speaker sounds more like a single preferred accent.","The roles, purpose, channel and local expectations of the interaction.","Whether the more formal speaker is automatically more intelligent.","Whether informal language is always inappropriate in service."],"correctAnswer":"The roles, purpose, channel and local expectations of the interaction.","explanation":"Roles and conventions help explain register choices. Accent or formality alone does not measure intelligence or respect.","hint":"Describe the interactional context before evaluating the language choice.","errorFocus":"REGISTER_USED_AS_PERSONAL_WORTH_RANKING","misconceptions":{"Which speaker sounds more like a single preferred accent.":["REGISTER_USED_AS_PERSONAL_WORTH_RANKING"]},"position":7},{"id":"v5-english-relate-language-culture-23","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"HUMOR_AND_RELATIONSHIP","statement":"A friend replies “Very subtle!” after another friend arrives wearing a bright costume for a theme day. What clue supports a playful reading?","options":["The phrase always expresses anger.","The costume proves the speaker is making a formal complaint.","The exaggerated contrast between “subtle” and the bright costume, together with the friends’ context.","The words have no relation to what happened."],"correctAnswer":"The exaggerated contrast between “subtle” and the bright costume, together with the friends’ context.","explanation":"The contrast may signal playful irony in this relationship. Tone and shared context matter, so the phrase should not be interpreted universally.","hint":"Compare the literal adjective with the visible situation and relationship.","errorFocus":"IRONY_LITERALIZED_WITHOUT_CONTEXT","misconceptions":{"The phrase always expresses anger.":["IRONY_LITERALIZED_WITHOUT_CONTEXT"]},"position":8},{"id":"v5-english-relate-language-culture-24","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"ACCENT_PRESTIGE_BIAS","statement":"A student says one English accent is “more intelligent” than another. Which response uses linguistic evidence responsibly?","options":["Agree because one accent is used more in films.","Treat accent as proof of education or intelligence.","Assume every listener understands one accent equally.","Ask what feature is being discussed and separate intelligibility or context from judgments about a speaker’s worth."],"correctAnswer":"Ask what feature is being discussed and separate intelligibility or context from judgments about a speaker’s worth.","explanation":"Accent judgments can reflect social attitudes. A specific communication question should be evaluated in context, not used to rank people.","hint":"Replace the broad ranking with a specific, observable communication question.","errorFocus":"ACCENT_AS_INTELLIGENCE_PROXY","misconceptions":{"Agree because one accent is used more in films.":["ACCENT_AS_INTELLIGENCE_PROXY"]},"position":1},{"id":"v5-english-relate-language-culture-25","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"TWO_NOTICES_AUDIENCE","statement":"Notice A says “Staff: please sign in at reception.” Notice B says “Visitors, please check in at the front desk.” What explains the wording difference most directly?","options":["The notices address different audiences and use terms suited to each setting.","One notice proves its audience is more important.","The difference shows one sentence is not English.","The wording must be identical because both mention sign-in."],"correctAnswer":"The notices address different audiences and use terms suited to each setting.","explanation":"Both notices communicate a similar action while naming different audiences and using locally familiar terms.","hint":"Compare who each notice addresses and where it will be displayed.","errorFocus":"AUDIENCE_DIFFERENCE_RANKED_AS_LANGUAGE_QUALITY","misconceptions":{"One notice proves its audience is more important.":["AUDIENCE_DIFFERENCE_RANKED_AS_LANGUAGE_QUALITY"]},"position":2},{"id":"v5-english-relate-language-culture-26","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CULTURAL_STEREOTYPE_CHECK","statement":"A joke uses a broad claim about a nationality as its punchline. What is a careful first response in an intercultural discussion?","options":["Repeat the claim as a reliable description of everyone in that group.","Examine who is represented, who is targeted, the context and possible effects instead of treating the stereotype as a fact.","Assume the joke has the same effect on every audience.","Ignore the people represented because it is only language."],"correctAnswer":"Examine who is represented, who is targeted, the context and possible effects instead of treating the stereotype as a fact.","explanation":"A stereotype is not evidence about a whole group. Analyze the framing and possible effects without assuming one universal response.","hint":"Identify the claim, the people represented and the missing evidence.","errorFocus":"STEREOTYPE_AS_FACT_OR_UNIVERSAL_RECEPTION","misconceptions":{"Repeat the claim as a reliable description of everyone in that group.":["STEREOTYPE_AS_FACT_OR_UNIVERSAL_RECEPTION"]},"position":3},{"id":"v5-english-relate-language-culture-27","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"SEQUENCE","contextFamily":"CONTEXT_ANALYSIS_METHOD","statement":"When interpreting an unfamiliar English message, which sequence is most reliable?","options":["Choose a cultural stereotype first and fit the message to it.","Translate every word literally before reading the situation.","Identify audience, purpose and channel; examine language clues; consider alternatives; state what remains uncertain.","Judge the speaker’s intelligence from formality."],"correctAnswer":"Identify audience, purpose and channel; examine language clues; consider alternatives; state what remains uncertain.","explanation":"Context and textual clues support a reading; considering alternatives and uncertainty prevents unsupported certainty.","hint":"Start with evidence in the interaction, not assumptions about a group.","errorFocus":"CONTEXT_METHOD_SKIPPED","misconceptions":{"Choose a cultural stereotype first and fit the message to it.":["CONTEXT_METHOD_SKIPPED"]},"position":1},{"id":"v5-english-relate-language-culture-28","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"REGISTER_NOT_PRESTIGE","statement":"Which statement best describes formal and informal English?","options":["Formal English is always better in every interaction.","Informal English is always incorrect.","The same register is required in every community and channel.","They are choices that can fit different purposes and relationships; neither is a universal measure of a person’s ability."],"correctAnswer":"They are choices that can fit different purposes and relationships; neither is a universal measure of a person’s ability.","explanation":"Appropriateness depends on context. Register choices do not rank speakers’ human worth or overall ability.","hint":"Ask “fit for which audience and purpose?” rather than “which is superior?”","errorFocus":"REGISTER_HIERARCHY","misconceptions":{"Formal English is always better in every interaction.":["REGISTER_HIERARCHY"]},"position":2},{"id":"v5-english-relate-language-culture-29","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"TRANSFER","contextFamily":"ASK_FOR_CLARIFICATION","statement":"A phrase could be either a local idiom or a literal instruction, and the surrounding message does not resolve it. What is a useful response?","options":["Ask a neutral clarifying question rather than pretending certainty.","Choose the most dramatic interpretation and act on it.","Assume the literal meaning is always correct.","Attribute the ambiguity to the writer’s culture without asking."],"correctAnswer":"Ask a neutral clarifying question rather than pretending certainty.","explanation":"When context is insufficient, clarification is more reliable than guessing or attributing confusion to a whole culture.","hint":"Name the uncertainty and ask what the speaker means in this situation.","errorFocus":"UNCERTAINTY_FILLED_WITH_CULTURAL_ASSUMPTION","misconceptions":{"Choose the most dramatic interpretation and act on it.":["UNCERTAINTY_FILLED_WITH_CULTURAL_ASSUMPTION"]},"position":3}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 6, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-english-relate-language-culture-contextual-use',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 6
       and metadata->>'content_id' = 'v5-english-relate-language-culture-contextual-use' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'ENGLISH', 'LANGUAGE_AND_CULTURE', 'register_idioms_variety_and_audience',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

